def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the repeated-color strip, horizontal or vertical.
    palette = None
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != 0]
        if len(cols) >= 2 and cols == list(range(cols[0], cols[-1] + 1)):
            seq = [grid[r][c] for c in cols]
            if len(set(seq)) == len(seq) and all(
                [grid[rr][c] for c in cols] == seq
                for rr in range(h) if rr != r and
                [grid[rr][c] for c in cols] == seq
            ):
                # Require the identical sequence to occur on multiple rows.
                if sum(1 for rr in range(h)
                       if [grid[rr][c] for c in cols] == seq) >= 2:
                    palette = seq
                    break
    if palette is None:
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] != 0]
            if len(rows) >= 2 and rows == list(range(rows[0], rows[-1] + 1)):
                seq = [grid[r][c] for r in rows]
                if len(set(seq)) == len(seq) and sum(
                    1 for cc in range(w)
                    if [grid[r][cc] for r in rows] == seq
                ) >= 2:
                    palette = seq
                    break

    # Motif consists of the non-palette 1-colored cells.
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    # Keep the component away from the palette; normally the motif is a single
    # connected component while the palette's 1 is part of the strip.
    comps = []
    unseen = set(ones)
    while unseen:
        start = unseen.pop()
        stack = [start]
        comp = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    stack.append(p)
                    comp.append(p)
        comps.append(comp)
    shape_cells = max(comps, key=len)
    r0 = min(r for r, c in shape_cells)
    c0 = min(c for r, c in shape_cells)
    shape = [(r-r0, c-c0) for r, c in shape_cells]
    mh = max(dr for dr, dc in shape) + 1

    top = r0 - palette.index(1) * mh
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        for dr, dc in shape:
            rr, cc = top + i*mh + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    best_color, best_size = 0, 0

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            size = 0
            while stack:
                y, x = stack.pop()
                size += 1
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            if size > best_size:
                best_color, best_size = color, size

    return [[best_color] * 3 for _ in range(3)]

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find vertical marker columns: columns with a contiguous nonzero line
    # reaching the bottom of the grid.
    markers = []
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != 0]
        if rows and rows[-1] == h - 1 and len(rows) >= 2:
            markers.append(c)

    # Horizontal bars provide the colors for the vertical extensions.
    bar_rows = []
    for r in range(h):
        if sum(v != 0 for v in grid[r]) >= 3:
            bar_rows.append(r)

    for c in markers:
        for r in bar_rows:
            color = grid[r][c]
            if color == 0:
                # A marker may sit in the gap separating two parts of a bar.
                for d in (1, -1, 2, -2):
                    if 0 <= c + d < w and grid[r][c + d] != 0:
                        color = grid[r][c + d]
                        break
            if color:
                # Extend this bar's color upward to the top.
                for rr in range(r):
                    out[rr][c] = color
                out[r][c] = color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Continue diagonal lines of 1s between matching endpoints.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r1 != r2 and abs(r2-r1) == abs(c2-c1):
                sr = 1 if r2 > r1 else -1
                sc = 1 if c2 > c1 else -1
                for k in range(1, abs(r2-r1)):
                    out[r1+k*sr][c1+k*sc] = 1

    # Extend the 6 line only when a 6 lies on the diagonal between 1 markers.
    for r, c in sixes:
        if any(r1 != r2 and abs(r2-r1) == abs(c2-c1)
               and (r-r1)*(c2-c1) == (c-c1)*(r2-r1)
               and min(r1, r2) <= r <= max(r1, r2)
               and min(c1, c2) <= c <= max(c1, c2)
               for i, (r1, c1) in enumerate(ones)
               for r2, c2 in ones[i+1:]):
            # Draw the other diagonal through that 6.
            for sr in (-1, 1):
                sc = sr
                rr, cc = r + sr, c + sc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != 1:
                        out[rr][cc] = 6
                    rr += sr
                    cc += sc
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    # Recolor complete 2x2 blocks first.
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[i][j] == 8 for i in (r, r + 1) for j in (c, c + 1)):
                for i in (r, r + 1):
                    for j in (c, c + 1):
                        if out[i][j] == 0:
                            out[i][j] = 1
    # The remaining parts are the small L-shaped pieces.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or out[r][c]:
                continue
            # Determine an L piece's color from its orientation.
            if (c > 0 and r > 0 and grid[r-1][c] == 8 and grid[r][c-1] == 8):
                color = 2
            elif (c + 1 < w and r + 1 < h and grid[r][c+1] == 8 and grid[r+1][c] == 8):
                color = 3
            elif (c + 1 < w and r > 0 and grid[r-1][c] == 8 and grid[r][c+1] == 8):
                color = 4
            else:
                color = 2 if r >= h // 2 else 3
            out[r][c] = color
    return out

