    for r in range(1, R - 1):
        for c in range(1, C - 1):
            if (grid[r][c-1] == 2 and grid[r][c+1] == 2 and
                grid[r-1][c] == 2 and grid[r+1][c] == 2):
                motifs.append((r, c))
    # Link aligned motif arms across blank gaps.
    for r1, c1 in motifs:
        for r2, c2 in motifs:
            if r1 == r2 and c2 > c1:
                # Horizontal links between the right and left arms.
                if all(grid[r1][c] == 0 for c in range(c1+2, c2-1)):
                    for c in range(c1+2, c2-1):
                        out[r1][c] = 1
            if c1 == c2 and r2 > r1:
